// Faithful port of the static design in curago-landing_5.html.
// Server component (no client interactivity). The layout provides <html>/<head>/<body>.
// Placeholder CTAs wired to real routes; product URLs resolved from env with /signup fallback.

const BUNDLE_URL = process.env.NEXT_PUBLIC_BUNDLE_URL || '/signup';

const CSS = `@import url('https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600;700&family=Instrument+Serif:ital@0;1&family=DM+Mono:wght@400;500&display=swap');

  :root{
    --paper:#F7F9F5; --card:#FFFFFF; --ink:#101A13;
    --green:#096B17; --green-deep:#064010; --orange:#F26A1B;
    --muted:#5E6B5F; --rule:#DDE4D9; --rule-soft:#EDF1EB;
    --sans:"Instrument Sans",system-ui,sans-serif;
    --serif:"Instrument Serif",Georgia,serif;
    --mono:"DM Mono",ui-monospace,monospace;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html{scroll-behavior:smooth}
  body{background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:17px;line-height:1.55;-webkit-font-smoothing:antialiased}
  .wrap{max-width:1080px;margin:0 auto;padding:0 22px}
  @media(min-width:900px){ .wrap{padding:0 32px} }
  .narrow{max-width:760px;margin-left:auto;margin-right:auto}
  a{color:inherit}

  .btn{display:inline-block;font-family:var(--sans);font-size:16px;font-weight:600;background:var(--orange);color:#fff;border:0;border-radius:11px;padding:17px 32px;cursor:pointer;min-height:54px;text-decoration:none;transition:filter .15s;text-align:center}
  .btn:hover{filter:brightness(.93)}
  .btn:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
  .btn.big{font-size:18px;padding:19px 40px}
  .btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--rule)}
  .btn.ghost:hover{filter:none;background:var(--card);border-color:var(--ink)}
  .btn.light{background:#fff;color:var(--green-deep)}
  .btn.block{display:block;width:100%}
  .tlink{font-size:15.5px;font-weight:500;color:var(--ink);text-decoration:none;border-bottom:1px solid var(--rule);padding-bottom:2px}
  .tlink:hover{border-color:var(--ink)}
  .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:var(--green)}

  nav{border-bottom:1px solid var(--rule);background:rgba(247,249,245,.92);backdrop-filter:blur(8px);position:sticky;top:0;z-index:30}
  nav .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px;height:62px;max-width:1080px}
  .logo{display:flex;align-items:baseline;gap:9px;text-decoration:none}
  .logo b{font-size:18px;font-weight:700;letter-spacing:-.02em;color:var(--green)}
  .logo span{font-family:var(--mono);font-size:9.5px;letter-spacing:.11em;text-transform:uppercase;color:var(--muted)}
  nav .btn{padding:10px 18px;min-height:42px;font-size:14px}
  .navlinks{display:flex;gap:22px;align-items:center}
  .navlinks a{font-size:14.5px;font-weight:500;color:var(--muted);text-decoration:none}
  .navlinks a:hover{color:var(--ink)}
  @media(max-width:680px){ .navlinks{display:none} }

  /* ===== HERO = PRACTICE OS ===== */
  .hero{background:var(--green-deep);color:#fff;padding:66px 0 74px;overflow:hidden}
  @media(min-width:900px){ .hero{padding:88px 0 96px} }
  .herogrid{display:grid;grid-template-columns:1fr;gap:44px;align-items:center}
  @media(min-width:940px){ .herogrid{grid-template-columns:1.02fr .98fr;gap:60px} }
  .hero .eyebrow{color:#8FC79A}
  .hero h1{font-size:clamp(38px,5.6vw,62px);line-height:1.03;font-weight:600;letter-spacing:-.032em;margin:18px 0 20px;max-width:15ch}
  .hero h1 em{font-style:italic;font-family:var(--serif);font-weight:400}
  .hero .lede{font-size:18.5px;line-height:1.58;color:rgba(255,255,255,.78);max-width:46ch;margin-bottom:28px}
  .osfeat{list-style:none;margin:0 0 30px;padding:0}
  .osfeat li{padding:13px 0;border-top:1px solid rgba(255,255,255,.14);font-size:16px;line-height:1.5}
  .osfeat li:last-child{border-bottom:1px solid rgba(255,255,255,.14)}
  .osfeat li b{font-weight:600}
  .osfeat li span{color:rgba(255,255,255,.68)}
  .herocta{display:flex;flex-wrap:wrap;gap:14px 18px;align-items:center}
  .priceline{font-family:var(--mono);font-size:12.5px;color:#8FC79A;margin-top:16px;letter-spacing:.01em}
  .priceline b{color:#fff;font-weight:500}
  /* hero visual */
  .herovis{position:relative}
  .shotwrap{border-radius:13px;overflow:hidden;border:1px solid rgba(255,255,255,.16);box-shadow:0 26px 64px rgba(0,0,0,.34)}
  .shotwrap img{display:block;width:100%}
  .shot2{position:absolute;width:44%;right:-14px;bottom:-26px;border-radius:10px;overflow:hidden;border:1px solid rgba(255,255,255,.18);box-shadow:0 18px 40px rgba(0,0,0,.4)}
  .shot2 img{display:block;width:100%}
  @media(max-width:600px){ .shot2{display:none} }

  /* waitlist inline under hero cta */
  .wform{display:flex;flex-wrap:wrap;gap:10px;max-width:440px;margin-top:8px;width:100%}
  .wform input{flex:1;min-width:180px;font-family:var(--sans);font-size:15.5px;padding:15px 16px;border:1px solid rgba(255,255,255,.24);border-radius:10px;background:rgba(0,0,0,.22);color:#fff;min-height:52px}
  .wform input::placeholder{color:rgba(255,255,255,.45)}
  .wform input:focus{outline:2px solid var(--orange);outline-offset:1px}

  /* ===== HOW IT WORKS strip ===== */
  .how{padding:60px 0 10px}
  .how .sechead{text-align:center;margin-bottom:40px}
  .how h2{font-size:clamp(26px,3.3vw,38px);line-height:1.12;font-weight:600;letter-spacing:-.026em;margin:12px auto 12px;max-width:22ch}
  .how .sechead p{font-size:17.5px;color:var(--muted);max-width:52ch;margin:0 auto;line-height:1.6}
  .steps{display:grid;grid-template-columns:1fr;gap:20px;max-width:960px;margin:0 auto}
  @media(min-width:820px){ .steps{grid-template-columns:repeat(3,1fr)} }
  .step{background:var(--card);border:1px solid var(--rule);border-radius:15px;padding:26px}
  .step k{display:block;font-style:normal;font-family:var(--serif);font-size:32px;line-height:1;color:var(--green);margin-bottom:12px}
  .step h3{font-size:18px;font-weight:600;letter-spacing:-.015em;margin-bottom:7px}
  .step p{font-size:15px;line-height:1.55;color:var(--muted)}

  /* section frame */
  section.blk{padding:66px 0}
  @media(min-width:900px){ section.blk{padding:84px 0} }
  .sechead{text-align:center;margin-bottom:44px}
  .sechead h2{font-size:clamp(27px,3.5vw,40px);line-height:1.1;font-weight:600;letter-spacing:-.028em;margin:12px auto 14px;max-width:22ch}
  .sechead p{font-size:17.5px;line-height:1.6;color:var(--muted);max-width:54ch;margin:0 auto}

  /* ===== TWO PRODUCTS + BUNDLE ===== */
  .prods{display:grid;grid-template-columns:1fr;gap:20px;max-width:900px;margin:0 auto}
  @media(min-width:760px){ .prods{grid-template-columns:1fr 1fr} }
  .prod{background:var(--card);border:1px solid var(--rule);border-radius:18px;padding:30px;display:flex;flex-direction:column}
  .prod .ptag{font-family:var(--mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:12px;display:block}
  .prod h3{font-size:23px;font-weight:600;letter-spacing:-.02em;margin-bottom:8px}
  .prod .pd{font-size:15.5px;line-height:1.55;color:var(--muted);margin-bottom:20px}
  .price{display:flex;align-items:baseline;gap:9px;margin-bottom:20px;flex-wrap:wrap}
  .price b{font-family:var(--serif);font-size:40px;line-height:1;color:var(--ink)}
  .price e{font-style:normal;font-family:var(--mono);font-size:11px;color:var(--muted)}
  .inc{list-style:none;margin:0 0 24px;padding:0;flex:1}
  .inc li{position:relative;padding-left:23px;margin-bottom:10px;font-size:15px;line-height:1.5}
  .inc li::before{content:"";position:absolute;left:0;top:7px;width:11px;height:6px;border:solid var(--green);border-width:0 0 2px 2px;transform:rotate(-45deg)}
  .prod .foot{font-family:var(--mono);font-size:10.5px;color:var(--muted);margin-top:12px;text-align:center;line-height:1.6}

  /* bundle bar */
  .bundle{max-width:900px;margin:22px auto 0;background:var(--card);border:1px solid var(--green);box-shadow:0 0 0 1px var(--green);border-radius:16px;padding:24px 28px;display:flex;flex-wrap:wrap;gap:18px;align-items:center;justify-content:space-between}
  .bundle .bl{display:flex;flex-direction:column;gap:4px;min-width:250px;flex:1}
  .bundle .btag{font-family:var(--mono);font-size:10px;letter-spacing:.11em;text-transform:uppercase;color:var(--green)}
  .bundle h4{font-size:19px;font-weight:600;letter-spacing:-.015em}
  .bundle p{font-size:14.5px;color:var(--muted);line-height:1.5}
  .bundle .br{display:flex;align-items:center;gap:18px;flex-wrap:wrap}
  .bundle .bprice{display:flex;align-items:baseline;gap:8px}
  .bundle .bprice b{font-family:var(--serif);font-size:34px;line-height:1}
  .bundle .bprice s{font-family:var(--serif);font-size:19px;color:#A8B3A6;text-decoration:line-through}
  .bundle .bprice e{font-style:normal;font-family:var(--mono);font-size:10.5px;color:var(--green)}

  /* ===== FREE BUILDER LINE ===== */
  .freeline{border-top:1px solid var(--rule);border-bottom:1px solid var(--rule);background:var(--card)}
  .freeline .wrap{padding:26px 22px;display:flex;flex-wrap:wrap;gap:14px 22px;align-items:center;justify-content:center;text-align:center}
  .freeline p{font-size:16.5px;line-height:1.5}
  .freeline p b{font-weight:600}
  .freeline p span{color:var(--muted)}
  .freeline a{font-weight:600;color:var(--green);text-decoration:none;white-space:nowrap;border-bottom:1px solid var(--rule);padding-bottom:2px}
  .freeline a:hover{border-color:var(--green)}

  /* problem mini */
  .why{text-align:center}
  .why .eyebrow{color:var(--green)}
  .why h2{font-size:clamp(24px,3vw,34px);line-height:1.15;font-weight:600;letter-spacing:-.024em;margin:12px auto 12px;max-width:24ch}
  .why p{font-size:17px;line-height:1.6;color:var(--muted);max-width:56ch;margin:0 auto}

  /* faq */
  details{border-bottom:1px solid var(--rule);padding:19px 0}
  summary{font-size:17.5px;font-weight:600;letter-spacing:-.015em;cursor:pointer;list-style:none;display:flex;justify-content:space-between;gap:20px;align-items:center}
  summary::-webkit-details-marker{display:none}
  summary::after{content:"+";font-family:var(--mono);font-size:20px;color:var(--green);flex:none}
  details[open] summary::after{content:"–"}
  details p{font-size:16px;line-height:1.65;color:var(--muted);margin-top:13px;max-width:64ch}

  /* final */
  .final{background:var(--green-deep);color:#fff;text-align:center}
  .final h2{font-size:clamp(29px,4vw,46px);line-height:1.08;font-weight:600;letter-spacing:-.03em;margin-bottom:16px;max-width:18ch;margin-left:auto;margin-right:auto}
  .final h2 em{font-style:italic;font-family:var(--serif);font-weight:400}
  .final p{font-size:18px;color:rgba(255,255,255,.74);max-width:48ch;margin:0 auto 30px;line-height:1.55}
  .final .wform{margin:0 auto}
  .final .fine{font-family:var(--mono);font-size:11.5px;color:rgba(255,255,255,.55);margin-top:22px}
  .founder-mini{margin-top:38px}
  .founder-mini t{display:block;font-size:15.5px;font-weight:600}
  .founder-mini s{display:block;font-style:normal;text-decoration:none;font-size:13.5px;color:rgba(255,255,255,.6)}

  footer{padding:44px 0 40px;background:var(--paper)}
  .fbot{display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;font-family:var(--mono);font-size:11.5px;color:var(--muted)}
  .fbot a{color:var(--muted);text-decoration:none;margin-left:16px}
  .fbot a:hover{color:var(--ink)}
  @media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
`;

